use crate::model::Factor;
use anyhow::{bail,ensure,Context,Result};
use omeco::{EinCode,NestedEinsum,GreedyMethod,TreeSA,Initializer,ScoreFunction,optimize_code};
use rand::{Rng,SeedableRng,rngs::StdRng};
use serde::{Serialize,Deserialize};
use std::collections::{BTreeMap,BTreeSet,HashMap};
use tenferro_cpu::CpuEngine;
use tenferro_einsum::TypedTensorEinsumExt;
use tenferro_tensor::TypedTensor;

#[derive(Clone,Serialize,Deserialize)]
pub struct Step {pub inputs:Vec<usize>,pub output:usize,pub input_labels:Vec<Vec<usize>>,pub retained_labels:Vec<usize>,pub work:u64,pub output_entries:u64}
#[derive(Clone,Serialize,Deserialize)]
pub struct Plan {pub method:String,pub seed:Option<u64>,pub query:Vec<usize>,pub input_scopes:Vec<Vec<usize>>,pub steps:Vec<Step>,pub total_work:u64,pub largest_tensor:u64,pub largest_generated:u64,pub settings:serde_json::Value}
fn set(v:&[usize])->BTreeSet<usize>{v.iter().copied().collect()}
fn step(inputs:Vec<usize>,out:usize,labels:Vec<Vec<usize>>,retained:Vec<usize>)->Result<Step>{let union:BTreeSet<_>=labels.iter().flat_map(|x|x.iter().copied()).collect();ensure!(union.len()<63,"pair exceeds supported size");ensure!(set(&retained).is_subset(&union),"output labels not in inputs");Ok(Step{inputs,output:out,input_labels:labels,work:1u64<<union.len(),output_entries:1u64<<retained.len(),retained_labels:retained})}
fn from_tree(tree:&NestedEinsum<usize>,scopes:&[Vec<usize>],steps:&mut Vec<Step>)->Result<(usize,Vec<usize>)>{match tree{NestedEinsum::Leaf{tensor_index}=>Ok((*tensor_index,scopes.get(*tensor_index).context("bad leaf")?.clone())),NestedEinsum::Node{args,eins}=>{ensure!(!args.is_empty()&&args.len()<=2,"expected unary or binary optimizer node");let children:Vec<_>=args.iter().map(|x|from_tree(x,scopes,steps)).collect::<Result<_>>()?;let output=scopes.len()+steps.len();let inputs=children.iter().map(|x|x.0).collect();let labels=children.into_iter().map(|x|x.1).collect();let st=step(inputs,output,labels,eins.iy.clone())?;let out=st.retained_labels.clone();steps.push(st);Ok((output,out))}}}
pub fn create(factors:&[Factor],query:Vec<usize>,method:&str,seed:Option<u64>)->Result<Plan>{
 ensure!(!factors.is_empty(),"no non-scalar factors");let scopes:Vec<_>=factors.iter().map(|f|f.vars.clone()).collect();let mut steps=Vec::new();let mut settings=serde_json::json!({});
 if method=="random" {let mut rng=StdRng::seed_from_u64(seed.context("random requires seed")?);let mut live:BTreeMap<usize,Vec<usize>>=scopes.iter().cloned().enumerate().collect();while live.len()>1{let keys:Vec<_>=live.keys().copied().collect();let i=rng.gen_range(0..keys.len());let mut j=rng.gen_range(0..keys.len()-1);if j>=i{j+=1};let aa=keys[i];let bb=keys[j];let x=live.remove(&aa).unwrap();let y=live.remove(&bb).unwrap();let union:BTreeSet<_>=x.iter().chain(y.iter()).copied().collect();let outside:BTreeSet<_>=live.values().flatten().copied().chain(query.iter().copied()).collect();let keep=union.intersection(&outside).copied().collect();let id=scopes.len()+steps.len();let st=step(vec![aa,bb],id,vec![x,y],keep)?;live.insert(id,st.retained_labels.clone());steps.push(st);} }
 else {let code=EinCode::new(scopes.clone(),query.clone());let sizes:HashMap<usize,usize>=scopes.iter().flatten().map(|&v|(v,2)).collect();let tree=if method=="greedy"{optimize_code(&code,&sizes,&GreedyMethod::default())}else if method=="treesa"{ensure!(seed==Some(42),"omeco 0.2.6 TreeSA uses built-in seed 42 for its first trial");let config=TreeSA::new((0..150).map(|i|0.05+i as f64*0.1).collect(),1,20,Initializer::Greedy,ScoreFunction::time_optimized());settings=serde_json::json!({"seed":42,"trials":1,"iterations_per_beta":20,"beta_start":0.05,"beta_step":0.1,"beta_count":150,"score":"time only","initializer":"greedy","tie_breaking":"omeco 0.2.6 HashMap ordering may vary"});optimize_code(&code,&sizes,&config)}else{bail!("unknown ordering {method}")}.context("omeco failed to produce a plan")?;let (_root,labels)=from_tree(&tree,&scopes,&mut steps)?;ensure!(set(&labels)==set(&query),"optimizer returned wrong output labels");}
 let mut plan=Plan{method:method.into(),seed,query,input_scopes:scopes,steps,total_work:0,largest_tensor:1,largest_generated:1,settings};
 // OMECO provides a tree topology. Eliminate every index as soon as no live
 // outside factor or final output needs it, as specified by the learning sheet.
 let mut live:BTreeMap<usize,Vec<usize>>=plan.input_scopes.iter().cloned().enumerate().collect();
 for st in &mut plan.steps {let mut labels=Vec::new();for id in &st.inputs{labels.push(live.remove(id).context("optimizer references non-live input")?)}let union:BTreeSet<_>=labels.iter().flatten().copied().collect();let outside:BTreeSet<_>=live.values().flatten().copied().chain(plan.query.iter().copied()).collect();st.retained_labels=union.intersection(&outside).copied().collect();live.insert(st.output,st.retained_labels.clone());}
 analyze(&mut plan)?;Ok(plan)
}
pub fn analyze(plan:&mut Plan)->Result<()> {let mut live:BTreeMap<usize,Vec<usize>>=plan.input_scopes.iter().cloned().enumerate().collect();let mut work=0u64;let mut max_input=live.values().map(|s|1u64<<s.len()).max().unwrap_or(1);let mut generated=1;
 for (i,st) in plan.steps.iter_mut().enumerate(){ensure!(st.output==plan.input_scopes.len()+i,"invalid output id");ensure!(!st.inputs.is_empty()&&st.inputs.len()<=2,"invalid step arity");let mut labels=Vec::new();for id in &st.inputs{labels.push(live.remove(id).context("plan references non-live input")?)}
  let union:BTreeSet<_>=labels.iter().flatten().copied().collect();let outside:BTreeSet<_>=live.values().flatten().copied().chain(plan.query.iter().copied()).collect();let must:BTreeSet<_>=union.intersection(&outside).copied().collect();ensure!(set(&st.retained_labels)==must,"incorrect retained labels at step {i}: inputs={labels:?}, outside={outside:?}, expected={must:?}, got={:?}",st.retained_labels);let updated=step(st.inputs.clone(),st.output,labels,st.retained_labels.clone())?;work=work.checked_add(updated.work).context("work overflow")?;max_input=max_input.max(updated.output_entries);generated=generated.max(updated.output_entries);live.insert(updated.output,updated.retained_labels.clone());*st=updated;
 }ensure!(live.len()==1 && set(live.values().next().unwrap())==set(&plan.query),"incomplete plan or output mismatch");plan.total_work=work;plan.largest_tensor=max_input;plan.largest_generated=generated;Ok(())}
fn equation(inputs:&[&Factor],output:&[usize])->Result<String>{let labels:BTreeSet<_>=inputs.iter().flat_map(|f|f.vars.iter().copied()).collect();let alphabet:Vec<char>="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect();ensure!(labels.len()<=alphabet.len(),"too many labels in one pair");let map:HashMap<usize,char>=labels.into_iter().zip(alphabet).collect();let parts:Vec<String>=inputs.iter().map(|f|f.vars.iter().rev().map(|v|map[v]).collect()).collect();let out:String=output.iter().rev().map(|v|map[v]).collect();Ok(format!("{}->{}",parts.join(","),out))}
pub fn execute(factors:&[Factor],plan:&Plan,initial_log_scale:f64)->Result<(Factor,f64)>{let mut check=plan.clone();analyze(&mut check)?;ensure!(check.input_scopes==factors.iter().map(|f|f.vars.clone()).collect::<Vec<_>>(),"plan scopes do not match model");let mut cpu=CpuEngine::serial();let mut log_scale=initial_log_scale;let mut live:BTreeMap<usize,Factor>=BTreeMap::new();
 for (i,f) in factors.iter().enumerate(){let mut x=f.clone();let scale=x.data.iter().copied().fold(0.,f64::max);ensure!(scale>0.&&scale.is_finite(),"zero/nonfinite input factor");for v in &mut x.data{*v/=scale}log_scale+=scale.ln();live.insert(i,x);}
 for st in &plan.steps{let mut factors=Vec::new();for id in &st.inputs{factors.push(live.remove(id).context("missing live tensor")?)}let refs:Vec<_>=factors.iter().collect();let spec=equation(&refs,&st.retained_labels)?;let tensors:Vec<TypedTensor<f64>>=factors.iter().map(|f|TypedTensor::from_vec_col_major(vec![2;f.vars.len()],f.data.clone())).collect::<std::result::Result<_,_>>()?;let refs:Vec<_>=tensors.iter().collect();let result=refs.as_slice().einsum(&spec,&mut cpu).with_context(||format!("tenferro contraction {spec}"))?;let mut data=result.as_slice()?.to_vec();let scale=data.iter().copied().fold(0.,f64::max);ensure!(scale>0.&&scale.is_finite(),"zero/nonfinite intermediate");for v in &mut data{*v/=scale}log_scale+=scale.ln();live.insert(st.output,Factor{vars:st.retained_labels.clone(),data});}
 let (_,f)=live.into_iter().next().context("no output factor")?;Ok((f,log_scale))}
